var title = String(input.title || "数据报表");
var count = Number(input.count || 0);
var columns = Array.isArray(input.columns) ? input.columns : [];
var means = input.means || {};
var lines = ["# " + title, "", "- 记录数: " + count, "- 列: " + columns.join(", ")];
var keys = Object.keys(means);
if (keys.length > 0) {
  lines.push("", "| 列 | 均值 |", "| --- | --- |");
  keys.forEach(function (k) { lines.push("| " + k + " | " + means[k] + " |"); });
}
return { markdown: lines.join("\n") };
